bool IsRankFour(const TfLiteTensor* tensor) {
  return tensor != nullptr && tensor->dims != nullptr &&
         tensor->dims->size == 4;
}

bool HasPositiveDims(const TfLiteTensor* tensor) {
  if (!IsRankFour(tensor)) {
    return false;
  }
  for (int i = 0; i < 4; ++i) {
    if (tensor->dims->data[i] <= 0) {
      return false;
    }
  }
  return true;
}

cmsis_nn_dims ToCmsisDims(const TfLiteTensor* tensor) {
  return {tensor->dims->data[0], tensor->dims->data[1], tensor->dims->data[2],
          tensor->dims->data[3]};
}

