    return kTfLiteOk;
  }
  if (scratch_size > 0) {
    if (context == nullptr || context->RequestScratchBufferInArena == nullptr) {
      return kTfLiteOk;
    }
    int scratch_buffer_index = -1;
    if (context->RequestScratchBufferInArena(context, scratch_size,
